        self.assertEqual(self.report['semantics']['advanced_cache']['query_order'][0], ['getBrightness', 'getContrast', 'getSaturation', 'getWhiteBalance'])
        self.assertEqual(len(self.report['semantics']['advanced_cache']['query_order'][1]), 7)
