    def test_panel_definitions_and_first_match_priority_are_from_original(self):
        expected = {"80": [7], "83": [12], "103": [2, 7, 12], "141": [12], "143": [2, 6, 12],
                    "147": [2, 7, 12], "150": [12], "167": [2, 6, 12], "180": [12]}
