        self.reject("resetCalibration", "const t=3e3-(Date.now()-e)", "const t=2e3-(Date.now()-e)")
        self.reject("resetCalibration", "if(this.resetCalibrationInProgress=!1,t)throw",
            "if(this.resetCalibrationInProgress=!0,t)throw")
